create or replace force view apx_demo_approvals_v as
select a.approval_id
      ,a.doc_type
      ,d.doc_name
      ,a.doc_id
      ,a.doc_no
      ,a.approval_level
      ,a.approver_role
      ,a.amount
      ,a.requested_by
      ,a.requested_on
      ,a.status
      ,a.acted_by
      ,a.acted_on
      ,a.note
      ,apx_demo_approval_pkg.can_act_yn(a.approval_id) can_act_yn
  from apx_demo_approvals a
  join apx_demo_doc_types d on d.doc_type = a.doc_type;

create or replace force view apx_demo_user_roles_v as
select ur.user_role_id
      ,ur.username
      ,ur.role_code
      ,r.role_name
      ,ur.created_by
      ,ur.created_on
  from apx_demo_user_roles ur
  join apx_demo_roles r on r.role_code = ur.role_code;

create or replace force view apx_demo_departments_v as
select t.department_id
      ,t.dept_code
      ,t.dept_name
      ,t.active_yn
      ,t.created_by
      ,t.created_on
      ,t.updated_by
      ,t.updated_on
  from apx_demo_departments t;

create or replace force view apx_demo_items_v as
select t.item_id
      ,t.item_code
      ,t.item_name
      ,t.category
      ,t.uom
      ,t.std_price
      ,t.active_yn
      ,t.created_by
      ,t.created_on
      ,t.updated_by
      ,t.updated_on
  from apx_demo_items t;

create or replace force view apx_demo_requests_v as
select t.request_id
      ,t.request_no
      ,t.department_id
      ,(select dept_code || ' - ' || dept_name from apx_demo_departments r where r.department_id = t.department_id) department_id_dsp
      ,t.request_date
      ,t.need_date
      ,t.purpose
      ,t.notes
      ,t.status
      ,t.created_by
      ,t.created_on
      ,t.updated_by
      ,t.updated_on
  from apx_demo_requests t;

create or replace force view apx_demo_request_lines_v as
select t.line_id
      ,t.request_id
      ,(select request_no || ' - ' || purpose from apx_demo_requests r where r.request_id = t.request_id) request_id_dsp
      ,t.item_id
      ,(select item_code || ' - ' || item_name || ' (' || uom || ')' from apx_demo_items r where r.item_id = t.item_id) item_id_dsp
      ,t.qty
      ,t.unit_price
      ,t.line_amount
      ,t.created_by
      ,t.created_on
      ,t.updated_by
      ,t.updated_on
  from apx_demo_request_lines t;

create or replace force view apx_demo_dash_kpi_v as
select 1 seq
      ,'fa-check-square-o' icon
      ,'Approval Menunggu Anda' label
      ,(select count(*) from apx_demo_approvals_v where status = 'PENDING' and can_act_yn = 'Y') metric_value
  from dual
union all
select 2 seq
      ,'fa-file-o' icon
      ,'Permintaan Draft' label
      ,(select count(*) from apx_demo_requests where status = 'DRAFT') metric_value
  from dual
union all
select 3 seq
      ,'fa-clock-o' icon
      ,'Menunggu Approval' label
      ,(select count(*) from apx_demo_requests where status = 'SUBMITTED') metric_value
  from dual;

create or replace force view apx_demo_dash_c1_s1_v as
select status label, count(*) value from apx_demo_requests group by status;

create or replace force view apx_demo_dash_c2_s1_v as
select dept_name label, sum(total_amount) value from apx_demo_request_summary_v group by dept_name;
